    "ks.why.early-bird-flight": "Out before the light. You'd been awake a while, I think.",
    "ks.why.same-hour-twice": "Twice now, at the same hour. I'm starting to know when to wait by the door.",
    "ks.why.favorite-hour": "This is our hour. I've stopped being surprised by it.",
    "ks.why.favorite-day": "This day, more than any other. I keep the whole day free now.",
    "ks.why.late-return": "I came back long after dark. Someone was still awake, thinking about you.",
    "ks.why.first-reply": "The first time I brought something home instead of just taking it away.",
    "ks.why.first-morning-reply": "It was waiting when the day started. I flew it straight over.",
    "ks.why.first-midnight-reply": "They wrote back at midnight. I didn't wait until morning.",
    "ks.why.word-came-back": "One of your words came home in someone else's handwriting.",
    "ks.why.first-thread": "A letter turned into a correspondence. That doesn't happen every time.",
    "ks.why.first-turn-back": "You wrote again after they answered. That's when it stops being a reply and starts being a conversation.",
    "ks.why.five-letters-deep": "Five each way. From here, either of you can enclose a name.",
    "ks.why.you-signed-first": "You went first. That took something.",
    "ks.why.they-signed-first": "They went first — they chose to be known by you.",
    "ks.why.name-seal": "The first time you sealed your name into a letter.",
    "ks.why.first-kindred": "Two names crossed in my beak. I've been carrying letters for this.",
    "ks.why.three-kindreds": "Three people know your name now. I introduced all of them.",
    "ks.why.five-kindreds": "Five. There's a small crowd in your sky.",
    "ks.why.longest-thread": "The longest road I've flown between two people. Still going.",
    "ks.why.word-spotted": "You keep reaching for this one. I've started noticing it before you do.",
    "ks.why.first-voice-letter": "The first time what I carried had your voice in it, not just your hand.",
    "ks.why.first-sealed-page": "You gave me something to keep instead of deliver. It never left the house.",
    "ks.why.first-photo-kept": "A picture, sealed. Words aren't the only thing worth keeping.",
    "ks.why.first-drifted-line": "One line from your sealed pages asked to go out. I let it.",
    "ks.why.10-letters-carried": "Ten letters. My wings know the way now.",
    "ks.why.50-letters-carried": "Fifty. Some of these you don't even remember writing.",
    "ks.why.100-letters-carried": "A hundred letters carried. That's a lot of someone's life.",
    "ks.why.first-anniversary": "One year of this. I was an egg when we started.",
    "ks.evidence": "THE EVIDENCE",
    "ks.lineCarried": "A LINE SHE CARRIED",
    "ks.goCorrespondence": "GO TO THE CORRESPONDENCE",
    "ks.share": "SHARE THIS KEEPSAKE",
    "ks.happened": "This happened, and I kept it.",
    "ks.notYet": "Not yet. This one only exists once it really happens.",

