    /* ── help / write-to-us ── */
    "hp.title": "CÓMO FUNCIONA",
    "hp.intro": "Casi todas las preguntas de aquí son en realidad una regla que nadie te contó. Así que — las reglas.",
    "hp.q1": "¿Cómo encuentra una carta a alguien?",
    "hp.a1": "Nada de lo que escribes se difunde. {wren} lee cómo escribes — el ritmo, la forma de tus frases, las palabras que buscas — y lleva tu carta al extraño cuya escritura se acerca más a la tuya. Te emparejan por tu voz, nunca por edad, lugar ni una foto.",
    "hp.q2": "¿Por qué no puedo ver quién escribió esto?",
    "hp.a2": "Porque todavía no se han ganado el nombre del otro, y nadie más tampoco. Aquí todos son anónimos hasta que dos personas deciden lo contrario.",
    "hp.q3": "¿Cómo se intercambian los nombres?",
    "hp.a3": "A partir de cinco cartas cada uno, cualquiera de los dos puede incluir su nombre. No pasa nada hasta que el otro hace lo mismo — entonces {wren} lleva ambos a la vez. Si uno nunca firma, siguen siendo bellos extraños, y está bien.",
    "hp.q4": "¿Qué es mi aura?",
    "hp.a4": "Nueve señales en tu escritura — cómo empiezas, cuánto se alargan tus líneas, dónde pones el sentimiento. Cada una se fija solo cuando hay pruebas suficientes para confiar en ella, por eso se llena despacio y por eso nada se afirma pronto.",
    "hp.q5": "¿Alguien lee mis páginas selladas?",
    "hp.a5": "No, y no en el sentido en que lo dicen casi todas las apps. Tu diario sellado nunca sale de este teléfono. No se sube, no se respalda en nuestros servidores y queda deliberadamente fuera del emparejamiento — así no puede llegar a un extraño ni por accidente. {wren} tampoco las lee.",
    "hp.q6": "¿Por qué todo es tan lento?",
    "hp.a6": "Aquí nada está frenado. {wren} sale en cuanto pulsas enviar. Lo que tarda días es la persona del otro lado, viviendo su vida — y eso es el producto, no un retraso del que podríamos venderte la salida.",
    "hp.q7": "Alguien fue cruel. ¿Qué hago?",
    "hp.a7": "Abre los ⋯ en su carta. Reportar nos la envía; bloquear cierra el camino en ambos sentidos y se puede deshacer en Ajustes, en Bloqueados y reportados. Los reportes repetidos expulsan a un escritor de Kindredly.",
    "hp.q8": "¿Qué pasa si elimino mi cuenta?",
    "hp.a8": "Tus cartas se quedan en el mundo, sin firmar — un afín conserva lo que le escribiste, y nada lleva de vuelta a ti. Tus páginas selladas nunca salieron de este teléfono, así que se quedan. Todo lo demás se va, para siempre.",
    "wu.title": "ESCRÍBENOS",
    "wu.intro": "Todos aquí reciben una carta. Nosotros también — cuéntanos lo que sea.",
    "wu.ph": "escríbenos…",
    "wu.addrLabel": "DÓNDE RESPONDERTE — OPCIONAL",
    "wu.addrPh": "una dirección, si quieres respuesta",
    "wu.addrHint": "Déjalo en blanco y esto queda anónimo, como todo lo demás aquí — pero entonces no podemos responderte.",
    "wu.fail": "NO SALIÓ. INTÉNTALO EN UN MOMENTO.",
    "wu.send": "DÁSELA A {wren}",
    "wu.taken": "Se la ha llevado.",
    "wu.takenAddr": "Una persona lee esto — no un robot. Tendrás respuesta en la dirección que dejaste.",
    "wu.takenNoAddr": "Una persona lee esto — no un robot. No dejaste dirección, así que este es un vuelo de ida.",
    "wu.done": "LISTO",

